function zigzag(s, numRows) {
  if (numRows === 1) return s;
  const rows = Array(numRows).fill('');
  let idx = 0, dir = 1;
  for (const c of s) {
    rows[idx] += c;
    if (idx === 0) dir = 1;
    else if (idx === numRows - 1) dir = -1;
    idx += dir;
  }
  return rows.join('');
}
console.log(zigzag('PAYPALISHIRING', 3));

